<style>
/* Layout: one dark arena-night page, a pick row per role (hero, boss), then arenas, props and the lineup as reference. */
:root {
  --night: #0d0b17;
  --panel: #171428;
  --line: #2c2747;
  --ink: #ece8f6;
  --muted: #a39cc0;
  --cyan: #3fe6f0;
  --magenta: #ff3fae;
  --gold: #e7b84a;
  --display: "Chakra Petch", "Segoe UI", system-ui, sans-serif;
  --body: "IBM Plex Sans", "Segoe UI", system-ui, sans-serif;
  --mono: "IBM Plex Mono", ui-monospace, Consolas, monospace;
  color-scheme: dark;
}
body { background: var(--night); color: var(--ink); font-family: var(--body); font-size: 15px; line-height: 1.55; }
.wrap { max-width: 1180px; margin: 0 auto; padding-inline: 20px; padding-block: 36px 64px; display: grid; gap: 48px; }
header { display: grid; gap: 10px; }
.eyebrow { font-family: var(--mono); font-size: 12px; letter-spacing: .12em; text-transform: uppercase; color: var(--cyan); }
h1 { font-family: var(--display); font-weight: 700; font-size: clamp(30px, 5vw, 48px); line-height: 1.05; margin: 0; text-wrap: balance; }
h1 span { color: var(--magenta); }
.lede { color: var(--muted); max-width: 64ch; margin: 0; }
h2 { font-family: var(--display); font-weight: 700; font-size: 22px; margin: 0; letter-spacing: .02em; }
section { display: grid; gap: 16px; }
.sechead { display: flex; flex-wrap: wrap; align-items: baseline; justify-content: space-between; gap: 8px; border-bottom: 1px solid var(--line); padding-bottom: 8px; }
.sechead p { margin: 0; color: var(--muted); font-size: 14px; }
.grid { display: grid; gap: 20px; grid-template-columns: repeat(auto-fit, minmax(min(100%, 320px), 1fr)); }
.grid.wide { grid-template-columns: repeat(auto-fit, minmax(min(100%, 460px), 1fr)); }
figure { margin: 0; background: var(--panel); border: 1px solid var(--line); border-radius: 6px; overflow: hidden; display: grid; grid-template-rows: auto 1fr; min-width: 0; }
figure.pick { border-color: var(--cyan); box-shadow: 0 0 0 1px var(--cyan) inset; }
figure a { display: block; background: #c8c8cc; }
figure img { display: block; width: 100%; height: auto; }
.tall img { aspect-ratio: 2 / 3; object-fit: contain; }
figcaption { padding: 14px 16px 16px; display: grid; gap: 6px; }
.tag { display: flex; align-items: center; gap: 10px; font-family: var(--display); font-weight: 700; font-size: 18px; }
.code { font-family: var(--mono); font-weight: 400; font-size: 12px; color: var(--muted); }
.badge { font-family: var(--mono); font-size: 11px; letter-spacing: .08em; text-transform: uppercase; color: var(--night); background: var(--cyan); padding: 2px 7px; border-radius: 3px; }
figcaption p { margin: 0; color: var(--muted); font-size: 14px; }
.how { background: var(--panel); border: 1px solid var(--line); border-left: 3px solid var(--magenta); border-radius: 6px; padding: 16px 18px; display: grid; gap: 6px; max-width: 72ch; }
.how p { margin: 0; }
.how code { font-family: var(--mono); color: var(--gold); }
a:focus-visible, button:focus-visible { outline: 2px solid var(--magenta); outline-offset: 2px; }
.tabs { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 6px; }
.tabs button { font-family: var(--display); font-weight: 700; font-size: 16px; letter-spacing: .04em; color: var(--muted); background: var(--panel); border: 1px solid var(--line); border-radius: 4px; padding: 8px 18px; cursor: pointer; }
.tabs button[aria-selected="true"] { color: var(--night); background: var(--cyan); border-color: var(--cyan); }
.panel { display: grid; gap: 48px; }
.tracks { display: grid; gap: 14px; grid-template-columns: repeat(auto-fit, minmax(min(100%, 300px), 1fr)); }
.track { background: var(--panel); border: 1px solid var(--line); border-radius: 6px; padding: 14px 16px; display: grid; gap: 8px; min-width: 0; }
.track.wide { grid-column: 1 / -1; border-color: var(--magenta); }
.track p { margin: 0; color: var(--muted); font-size: 14px; }
.track audio { width: 100%; }
/* Models: per asset the sheet it came from beside a turnable view of what was made, then its numbers. */
.models { display: grid; gap: 20px; }
.model { background: var(--panel); border: 1px solid var(--line); border-radius: 6px; display: grid; grid-template-columns: minmax(0, 220px) minmax(0, 1fr); min-width: 0; overflow: hidden; }
.model .sheet { background: #c8c8cc; display: grid; place-items: center; }
.model .sheet img { display: block; width: 100%; height: 100%; max-height: 420px; object-fit: contain; }
.model .stage { display: grid; grid-template-rows: auto auto; min-width: 0; }
.model model-viewer { width: 100%; height: 420px; max-width: 100%; background: radial-gradient(circle at 50% 40%, #2a2546 0%, #120f20 75%); --poster-color: transparent; }
.model .info { padding: 14px 16px 16px; display: grid; gap: 10px; border-top: 1px solid var(--line); }
.model .info p { margin: 0; color: var(--muted); font-size: 14px; }
.stats { display: flex; flex-wrap: wrap; gap: 6px 18px; margin: 0; font-family: var(--mono); font-size: 13px; font-variant-numeric: tabular-nums; }
.stats div { display: flex; gap: 6px; }
.stats dt { color: var(--muted); }
.stats dd { margin: 0; color: var(--ink); }
.controls { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; }
.controls select, .controls button { font-family: var(--mono); font-size: 13px; color: var(--ink); background: var(--night); border: 1px solid var(--line); border-radius: 4px; padding: 5px 9px; }
.controls button { cursor: pointer; }
.controls button[aria-pressed="true"] { border-color: var(--cyan); color: var(--cyan); }
.state { font-family: var(--mono); font-size: 11px; letter-spacing: .08em; text-transform: uppercase; color: var(--night); background: var(--gold); padding: 2px 7px; border-radius: 3px; }
.views { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 6px; }
.views img { width: 100%; background: #f2f2f4; border-radius: 3px; display: block; }
.cards { display: grid; gap: 20px; grid-template-columns: repeat(auto-fit, minmax(min(100%, 300px), 1fr)); }
@media (max-width: 700px) {
  .model { grid-template-columns: minmax(0, 1fr); }
  .model .sheet img { max-height: 260px; }
  .model model-viewer { height: 340px; }
